        {
            pa0 = aOk0 != 0 ? A.AsAligned16()[aBase0 + ((0) >> 2)] : default(F4);
            pa1 = aOk1 != 0 ? A.AsAligned16()[aBase1 + ((0) >> 2)] : default(F4);
            pa2 = aOk2 != 0 ? A.AsAligned16()[aBase2 + ((0) >> 2)] : default(F4);
            pa3 = aOk3 != 0 ? A.AsAligned16()[aBase3 + ((0) >> 2)] : default(F4);
